import type { App } from 'vue';

import { createRouter, createWebHashHistory } from 'vue-router';
// oxlint-disable-next-line typescript/ban-ts-comment
// @ts-ignore -- routes is a virtual module generated by unplugin-vue-router
import { routes } from 'vue-router/auto-routes';

import { isLoggedIn, onSessionExpired } from '@fast-vue3/utils';

import NProgress from 'nprogress';

import Layout from '../layout/index.vue';

import 'nprogress/nprogress.css';

const AUTH_ROUTES = new Set(['/login']);
const WHITE_LIST = ['/login', '/error/403', '/error/404', '/error/500'];

export function setupRouter(app: App) {
  const authRoutes = (routes as any[]).filter((r) =>
    AUTH_ROUTES.has(r.path as string),
  );
  const appRoutes = (routes as any[]).filter(
    (r) => !AUTH_ROUTES.has(r.path as string),
  );

  const router = createRouter({
    history: createWebHashHistory(import.meta.env.BASE_URL),
    routes: [
      {
        path: '/',
        component: Layout,
        redirect: '/home',
        children: appRoutes,
      },
      ...authRoutes,
      { path: '/:pathMatch(.*)*', redirect: '/error/404' },
    ],
    scrollBehavior: () => ({ top: 0 }),
  });

  router.beforeEach((to) => {
    NProgress.start();
    const authenticated = isLoggedIn();

    if (WHITE_LIST.some((p) => to.path.startsWith(p))) {
      if (authenticated && to.path === '/login') return { path: '/' };
      return true;
    }
    if (!authenticated)
      return { path: '/login', query: { redirect: to.fullPath } };
    return true;
  });

  const stop = onSessionExpired(() => {
    const current = router.currentRoute.value;
    if (current.path !== '/login') {
      void router.replace({
        path: '/login',
        query: { redirect: current.fullPath },
      });
    }
  });
  app.onUnmount(stop);

  router.afterEach(() => NProgress.done());

  app.use(router);
  return router;
}
